sysevent_script_action.script:
try {
    // parm1 = array of fund details such as client, fund family, sla, statement date department
    //parm2 = email body
    var sub = event.parm1.split(","); // MSSFunds-4: Get Fund Details
    var client = sub[0].trim(); // Take Client Values
    var family = sub[1].trim(); //Take Family
    var department = sub[2].trim(); //Take Department
    var grTask = new GlideRecord('x_hsb11_mss_fund_0_funds_task'); // MSSFUNDS-4: Check if funds task exist for chaser email
    grTask.addEncodedQuery("fund_name.fund_family=" + family + "^department=" + department + "^state=1");
    grTask.query();
    if (grTask.next()) {
        //call for chaser and 30mins timer for chaser
        var emailSysID = new x_hsb11_mss_fund_0.MSS_Funds_Utils().createChaserRecord(event.parm1, event.parm2); // call function: parm1 = array of fund details, parm2 = subject line
        if (emailSysID != "") { // Check if chaser triggered
            var currDate = new GlideDateTime();
            currDate.addSeconds(1800); //MSSFUNDS-4: Add 30mins timer
            //MSSFUNDS-4: Schedule an event to check if no response received in 30mins then assign the task to FAOps
            gs.eventQueueScheduled('x_hsb11_mss_fund_0.assign_break_to_faops', current, event.parm1.toString(), event.parm2.toString(), currDate);
        }
    }
} catch (e) {
    gs.info("Unknown Exception While Processing Email Chaser Event" + e);
}
